#include <stdio.h>

int total(int *p, int n) {
    int sum = 0;
    for (int *q = p; q < p + n; q++) {
        sum = sum + *q;
    }
    return sum;
}

int main(void) {
    int bowls[8];
    int n;

    if (scanf("%d", &n) != 1) {
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    printf("一共 %d 条{unit}\n", total(bowls, n));
    return 0;
}
